export const Default = (args) => {
  const { align, alignDeprecated, defaultOpen, ...rest } = args;
  const resolvedAlign = alignDeprecated || align;
  return (
    <div style={{ margin: '3rem' }}>
      <IconButton
        key={defaultOpen ? 'open' : 'closed'}
        align={resolvedAlign}
        defaultOpen={defaultOpen}
        {...rest}>
        <Edit />
      </IconButton>
    </div>
  );
};

Default.args = {
  align: 'bottom',
  defaultOpen: true,
  disabled: false,
  label: 'Custom label',
  kind: 'primary',
};

Default.argTypes = {
  align: {
    options: alignOptions,
    control: {
      type: 'select',
    },
  },
  alignDeprecated: {
    name: 'align (deprecated)',
    options: deprecatedAlignOptions,
    control: {
      type: 'select',
    },
    table: {
      category: 'Deprecated',
    },
  },
  disabled: {
    control: {
      type: 'boolean',
    },
  },
  defaultOpen: {
    control: {
      type: 'boolean',
    },
  },
  label: {
    control: {
      type: 'text',
    },
  },
  kind: {
    control: {
      type: 'select',
    },
    options: ['primary', 'secondary', 'ghost', 'tertiary'],
  },
};

export const withBadgeIndicator = (args) => {
  return (
    <div style={{ margin: '3rem' }}>
      <IconButton
        label="Notification"
        kind="ghost"
        size="lg"
        autoAlign
        {...args}>
        <Notification />
      </IconButton>
    </div>
  );
};

withBadgeIndicator.args = {
  badgeCount: 4,
};
withBadgeIndicator.parameters = {
  controls: {
    exclude: ['size', 'kind'],
  },
};
